"""Monthly per-account totals from a CSV of transactions. See task.md."""

from __future__ import annotations

import datetime
import os
import re

REQUIRED_COLUMNS = ("id", "date", "account", "amount", "currency")
SUMMARY_HEADER = ("account", "month", "currency", "count", "total")
REJECTS_HEADER = ("record", "id", "reason")

_CHUNK = re.compile(r'[^,"\r\n]*(?:\r(?!\n)[^,"\r\n]*)*')
_QUOTED = re.compile(r'"([^"]*(?:""[^"]*)*)"')
_DATE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")
_AMOUNT = re.compile(r"(-?)([0-9]+)(?:\.([0-9]{1,4}))?")
_CURRENCY = re.compile(r"[A-Z]{3}")


class RollupError(ValueError):
    """Raised for an input file that cannot be rolled up at all."""


def build(input_csv: str, out_dir: str) -> None:
    """Read `input_csv`; write `<out_dir>/summary.csv` and `<out_dir>/rejects.csv`."""
    with open(input_csv, "rb") as handle:
        text = handle.read().decode("utf-8-sig")
    records = list(_records(text))
    if not records:
        raise RollupError("input has no header record")
    header, _ = records[0]
    if len(set(header)) != len(header):
        raise RollupError("header repeats a column name")
    missing = [name for name in REQUIRED_COLUMNS if name not in header]
    if missing:
        raise RollupError("header lacks required columns: " + ", ".join(missing))
    columns = {name: header.index(name) for name in REQUIRED_COLUMNS}
    width = len(header)

    seen_ids = set()
    currency_of = {}
    totals = {}
    rejects = []
    for number, (fields, bad) in enumerate(records[1:], start=1):
        parsed = _parse(fields, bad, width, columns)
        reason = None
        if parsed is None:
            reason = "malformed"
        else:
            record_id, account, month, currency, units = parsed
            if record_id in seen_ids:
                reason = "duplicate-id"
            elif currency_of.get(account, currency) != currency:
                reason = "currency-mismatch"
        if reason is None:
            seen_ids.add(record_id)
            currency_of.setdefault(account, currency)
            count, total = totals.get((account, month), (0, 0))
            totals[(account, month)] = (count + 1, total + units)
        else:
            id_index = columns["id"]
            record_id = fields[id_index] if id_index < len(fields) else ""
            rejects.append(_csv_line([str(number), record_id, reason]))

    summary = [_csv_line(SUMMARY_HEADER)]
    for account, month in sorted(totals):
        count, total = totals[(account, month)]
        summary.append(
            _csv_line([account, month, currency_of[account], str(count), _money(total)])
        )

    os.makedirs(out_dir, exist_ok=True)
    _write(os.path.join(out_dir, "summary.csv"), summary)
    _write(os.path.join(out_dir, "rejects.csv"), [_csv_line(REJECTS_HEADER), *rejects])


def _records(text):
    end = len(text)
    pos = 0
    while pos < end:
        if text[pos] == "\n":
            pos += 1
            continue
        if text.startswith("\r\n", pos):
            pos += 2
            continue
        fields = []
        bad_record = False
        while True:
            value, pos, bad = _field(text, pos)
            fields.append(value)
            bad_record = bad_record or bad
            if pos >= end:
                break
            if text[pos] == ",":
                pos += 1
            elif text[pos] == "\n":
                pos += 1
                break
            else:
                pos += 2
                break
        yield fields, bad_record


def _field(text, pos):
    """Return (value, next position, whether the field broke RFC 4180 quoting)."""
    end = len(text)
    bad = False
    parts = []
    if pos < end and text[pos] == '"':
        match = _QUOTED.match(text, pos)
        if match is None:
            return text[pos + 1 :], end, True
        parts.append(match.group(1).replace('""', '"'))
        pos = match.end()
        bad = not _ends_field(text, pos)
    while True:
        match = _CHUNK.match(text, pos)
        parts.append(match.group())
        pos = match.end()
        if pos < end and text[pos] == '"':
            parts.append('"')
            pos += 1
            bad = True
            continue
        return "".join(parts), pos, bad


def _ends_field(text, pos):
    return pos >= len(text) or text[pos] in ",\n" or text.startswith("\r\n", pos)


def _parse(fields, bad, width, columns):
    """Return (id, account, month, currency, amount in 1/10000 units), or None if malformed."""
    if bad or len(fields) != width:
        return None
    record_id = fields[columns["id"]]
    account = fields[columns["account"]]
    date = fields[columns["date"]]
    amount = fields[columns["amount"]]
    currency = fields[columns["currency"]]
    if not record_id or not account:
        return None
    date_match = _DATE.fullmatch(date)
    if date_match is None:
        return None
    try:
        datetime.date(*(int(part) for part in date_match.groups()))
    except ValueError:
        return None
    amount_match = _AMOUNT.fullmatch(amount)
    if amount_match is None or _CURRENCY.fullmatch(currency) is None:
        return None
    units = int(amount_match[2]) * 10000 + int((amount_match[3] or "").ljust(4, "0"))
    if amount_match[1]:
        units = -units
    return record_id, account, date[:7], currency, units


def _money(units):
    cents, remainder = divmod(abs(units), 100)
    if remainder >= 50:
        cents += 1
    sign = "-" if units < 0 and cents else ""
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def _csv_line(values):
    cells = []
    for value in values:
        if any(char in value for char in ',"\r\n'):
            value = '"' + value.replace('"', '""') + '"'
        cells.append(value)
    return ",".join(cells) + "\n"


def _write(path, lines):
    with open(path, "wb") as handle:
        handle.write("".join(lines).encode("utf-8"))
